import{_ as l,H as e,f as a,i as t}from"./chunks/framework.BH2BK_3i.js";const o=JSON.parse('{"title":"直播回放：如何成为AI时代的合格前端？","description":"","frontmatter":{},"headers":[{"level":2,"title":"讲师介绍","slug":"讲师介绍","link":"#讲师介绍","children":[]},{"level":2,"title":"直播概览","slug":"直播概览","link":"#直播概览","children":[{"level":3,"title":"AI 工具的应用","slug":"ai-工具的应用","link":"#ai-工具的应用","children":[]},{"level":3,"title":"AI 带来的变革","slug":"ai-带来的变革","link":"#ai-带来的变革","children":[]},{"level":3,"title":"AI 辅助学习与成长","slug":"ai-辅助学习与成长","link":"#ai-辅助学习与成长","children":[]},{"level":3,"title":"未来前端开发的趋势","slug":"未来前端开发的趋势","link":"#未来前端开发的趋势","children":[]},{"level":3,"title":"专栏内容概述","slug":"专栏内容概述","link":"#专栏内容概述","children":[]},{"level":3,"title":"后 AI 时代的畅想","slug":"后-ai-时代的畅想","link":"#后-ai-时代的畅想","children":[]}]},{"level":2,"title":"时间线参考","slug":"时间线参考","link":"#时间线参考","children":[]}],"relativePath":"跟月影学前端智能体开发/直播回放：如何成为AI时代的合格前端？.md","filePath":"跟月影学前端智能体开发/直播回放：如何成为AI时代的合格前端？.md","lastUpdated":1795560976000}'),E={name:"跟月影学前端智能体开发/直播回放：如何成为AI时代的合格前端？.md"};function p(A,i,r,n,B,s){return e(),a("div",null,[...i[0]||(i[0]=[t('<h1 id="直播回放-如何成为ai时代的合格前端" tabindex="-1">直播回放：如何成为AI时代的合格前端？ <a class="header-anchor" href="#直播回放-如何成为ai时代的合格前端" aria-label="Permalink to &quot;直播回放：如何成为AI时代的合格前端？&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E6%9C%88%E5%BD%B1%E5%AD%A6%E5%89%8D%E7%AB%AF%E6%99%BA%E8%83%BD%E4%BD%93%E5%BC%80%E5%8F%91/images/%25E7%259B%25B4%25E6%2592%25AD%25E5%259B%259E%25E6%2594%25BE%25EF%25BC%259A%25E5%25A6%2582%25E4%25BD%2595%25E6%2588%2590%25E4%25B8%25BAAI%25E6%2597%25B6%25E4%25BB%25A3%25E7%259A%2584%25E5%2590%2588%25E6%25A0%25BC%25E5%2589%258D%25E7%25AB%25AF%25EF%25BC%259F/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E6%9C%88%E5%BD%B1%E5%AD%A6%E5%89%8D%E7%AB%AF%E6%99%BA%E8%83%BD%E4%BD%93%E5%BC%80%E5%8F%91/images/%25E7%259B%25B4%25E6%2592%25AD%25E5%259B%259E%25E6%2594%25BE%25EF%25BC%259A%25E5%25A6%2582%25E4%25BD%2595%25E6%2588%2590%25E4%25B8%25BAAI%25E6%2597%25B6%25E4%25BB%25A3%25E7%259A%2584%25E5%2590%2588%25E6%25A0%25BC%25E5%2589%258D%25E7%25AB%25AF%25EF%25BC%259F/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E6%9C%88%E5%BD%B1%E5%AD%A6%E5%89%8D%E7%AB%AF%E6%99%BA%E8%83%BD%E4%BD%93%E5%BC%80%E5%8F%91/images/%25E7%259B%25B4%25E6%2592%25AD%25E5%259B%259E%25E6%2594%25BE%25EF%25BC%259A%25E5%25A6%2582%25E4%25BD%2595%25E6%2588%2590%25E4%25B8%25BAAI%25E6%2597%25B6%25E4%25BB%25A3%25E7%259A%2584%25E5%2590%2588%25E6%25A0%25BC%25E5%2589%258D%25E7%25AB%25AF%25EF%25BC%259F/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E6%9C%88%E5%BD%B1%E5%AD%A6%E5%89%8D%E7%AB%AF%E6%99%BA%E8%83%BD%E4%BD%93%E5%BC%80%E5%8F%91/images/%25E7%259B%25B4%25E6%2592%25AD%25E5%259B%259E%25E6%2594%25BE%25EF%25BC%259A%25E5%25A6%2582%25E4%25BD%2595%25E6%2588%2590%25E4%25B8%25BAAI%25E6%2597%25B6%25E4%25BB%25A3%25E7%259A%2584%25E5%2590%2588%25E6%25A0%25BC%25E5%2589%258D%25E7%25AB%25AF%25EF%25BC%259F/2.jpeg" alt=""></a></p><h2 id="讲师介绍" tabindex="-1">讲师介绍 <a class="header-anchor" href="#讲师介绍" aria-label="Permalink to &quot;讲师介绍&quot;">​</a></h2><p>月影，六北科技 CTO。前奇虎 360 奇舞团团长，拥有 20 年开发经验的资深前端专家，熟悉JavaScript 相关的开发工作，著有《JavaScript 王者归来》。月影非常热爱写代码，一直在做一线项目开发，并坚持技术输出。近两年在大模型产品开发方面积累了比较丰富的实践经验。</p><h2 id="直播概览" tabindex="-1">直播概览 <a class="header-anchor" href="#直播概览" aria-label="Permalink to &quot;直播概览&quot;">​</a></h2><p>AI 将改变前端开发的底层范式和程序员的核心技能逻辑。前端行业会存在但会发生变化，开发者需适应新的开发方式，比如“面向 AI 编程”。这次直播，我们邀请月影老师分享他对“如何成为 AI 时代的合格前端”的观点与实践。</p><h3 id="ai-工具的应用" tabindex="-1">AI 工具的应用 <a class="header-anchor" href="#ai-工具的应用" aria-label="Permalink to &quot;AI 工具的应用&quot;">​</a></h3><ul><li><p>推荐使用 AI 工具帮助前端开发，如代码生成、提示词工程等。</p></li><li><p>开发者不仅会用工具，还能打造适合自己的工具。示例：通过 AI 实现无代码或低代码的前端工作流。</p></li></ul><h3 id="ai-带来的变革" tabindex="-1">AI 带来的变革 <a class="header-anchor" href="#ai-带来的变革" aria-label="Permalink to &quot;AI 带来的变革&quot;">​</a></h3><ul><li><p>面向 AI 编程：从写代码到写提示词，AI 根据环境生成最适合的代码。</p></li><li><p>工具链构建：如 DeepSeek、GPT 等提供 API，前端可通过调用 API 快速开发应用。</p></li><li><p>案例演示：智能收藏助手：基于飞书多维表格和 COS 平台实现网页收藏、转写英文文章等功能；玩偶生成器：通过提示词生成图片，适用于副业或商业应用。</p></li><li><p>零框架：用于解析 JSON 数据流，优化复杂工作流性能。</p></li></ul><h3 id="ai-辅助学习与成长" tabindex="-1">AI 辅助学习与成长 <a class="header-anchor" href="#ai-辅助学习与成长" aria-label="Permalink to &quot;AI 辅助学习与成长&quot;">​</a></h3><ul><li><p>使用 AI 总结文章核心观点、构建知识图谱、生成复习问题等。</p></li><li><p>快速迁移知识：如通过概念映射对比学习新框架（React ↔ Jetpack Compose）。</p></li><li><p>提高学习效率：AI 生成个性化学习计划，扫描知识盲点。</p></li></ul><h3 id="未来前端开发的趋势" tabindex="-1">未来前端开发的趋势 <a class="header-anchor" href="#未来前端开发的趋势" aria-label="Permalink to &quot;未来前端开发的趋势&quot;">​</a></h3><ul><li><p>核心能力从“写代码”转向“让 AI 写代码”。</p></li><li><p>跨框架、跨语言抽象能力成为关键技能。</p></li><li><p>创造力、审美力及持续学习能力的重要性提升。</p></li></ul><h3 id="专栏内容概述" tabindex="-1">专栏内容概述 <a class="header-anchor" href="#专栏内容概述" aria-label="Permalink to &quot;专栏内容概述&quot;">​</a></h3><p>七大单元</p><ul><li><p>大模型应用基础：介绍 DeepSeek 等主流 ai 工具的调用方法及最佳实践。</p></li><li><p>提示词工程与零框架性能优化。</p></li><li><p>综合实战项目一：复杂结构化内容生成（如“波波熊学伴”）。</p></li><li><p>综合实战项目二：多轮对话设计（如“AI 面试官”）。</p></li><li><p>个人 AI 效能工具：代码辅助、学习工具开发。</p></li><li><p>企业 AI 应用：私有化部署、企业知识库建设。</p></li><li><p>前沿技术趋势：Web LLM、端侧模型等。</p></li></ul><p>课程特色：</p><ul><li><p>注重底层原理与实操。</p></li><li><p>不仅适用于 AI 开发，还可扩展至其他高并发并行工作流。</p></li></ul><h3 id="后-ai-时代的畅想" tabindex="-1">后 AI 时代的畅想 <a class="header-anchor" href="#后-ai-时代的畅想" aria-label="Permalink to &quot;后 AI 时代的畅想&quot;">​</a></h3><ul><li><p>AI 不会完全取代开发者，而是通过协作提升效率。</p></li><li><p>平庸的人可能被淘汰，优秀的人借助 AI 更优秀。</p></li><li><p>AI 管理学：需要对 AI 进行考核、反馈与管理。</p></li></ul><h2 id="时间线参考" tabindex="-1">时间线参考 <a class="header-anchor" href="#时间线参考" aria-label="Permalink to &quot;时间线参考&quot;">​</a></h2><ul><li><p>00:00:00～00:02:13 开场 &amp; 个人介绍</p></li><li><p>00:02:14～00:07:39 前端在 AI 时代的变革与机遇</p></li><li><p>00:07:40～00:11:29 前端开发者的优势 &amp; 开发范式的变化</p></li><li><p>00:11:30～00:25:52 如何为自己打造 AI 专属工具</p></li><li><p>00:25:53～00:31:02 打造 AI 工具链 &amp; 对工作流的理解</p></li><li><p>00:31:03～00:40:27 复杂结构内容快速生成 &amp; Ling 框架</p></li><li><p>00:40:28～00:43:24 AI 面试官项目（多轮对话问题处理）</p></li><li><p>00:43:25～00:47:05 打造 AI 工具的最佳实践</p></li><li><p>00:47:06～00:56:36 构建个人知识体系的 AI 辅助方案</p></li><li><p>00:56:37～00:57:30 AI 辅助学习的最佳实践</p></li><li><p>00:57:31～01:03:21 写代码的前端工程师（AI 生成 PPT/ 网页）</p></li><li><p>01:03:22～01:11:38 后 AI 时代，前端拥有怎样的未来</p></li><li><p>01:11:39～01:11:31 课程介绍（实操智能体开发 ，但不止于此）</p></li><li><p>01:11:32～01:41:52 直播答疑互动</p></li></ul>',24)])])}const u=l(E,[["render",p]]);export{o as __pageData,u as default};
